import {expect, test} from 'bun:test';
import {AppleSrp} from './apple-srp.ts';

// Independent known answers: reviewer used Ruby 2.6/OpenSSL SHA256/PBKDF2 and
// Integer.pow, applying cocagne/pysrp H/HNxorg/gen_x/calculate_M/H_AMK formulas
// plus icloudpd 879c561's password transform. Not generated by @foxt/js-srp.
// B=2 deliberately exercises minimal proof encoding versus RFC5054 padding.
const privateValue = 0x60975527035cf2ad1989806f0407210bc81edc04e2762a56afd529ddda2d4393n;
const challenge = {salt: Buffer.from('beb25379d1a8581eb5a727673a2441ee', 'hex').toString('base64'), iteration: 1000, b: 'Ag==', c: 'fixture-challenge'};
const expectedA = '';

for (const vector of [
  {protocol: 's2k' as const, m1: '67a052a95c16bf617d8db0c485556484fa21167866b1958aaf8e531824391c7d', m2: '2f0871761af4e3c066f547237d86e5ef59f20ddc8afd6685f21db9165b0714c3'},
  {protocol: 's2k_fo' as const, m1: '19994e1590cc851964ed746a276dded745cf11b8428ca8a0a35e1869222bdd31', m2: '9e3e1dda5f368169c3e7b6b5790db1fdda736c22e2da05cf0b8527f0291e9161'},
]) {
  test(`Apple SRP ${vector.protocol} matches independent OpenSSL known answers`, async () => {
    const client = await AppleSrp.create('alice', privateValue);
    expect(Buffer.from(client.publicKey, 'base64').toString('hex')).toBe(expectedA);
    const proof = await client.complete('password123', {...challenge, protocol: vector.protocol});
    expect(Buffer.from(proof.m1, 'base64').toString('hex')).toBe(vector.m1);
    expect(Buffer.from(proof.m2, 'base64').toString('hex')).toBe(vector.m2);
    await expect(client.complete('password123', {...challenge, protocol: vector.protocol})).rejects.toThrow('already consumed');
  });
}

test('SRP rejects invalid server parameters before derivation', async () => {
  for (const patch of [{b:'AA=='}, {b:Buffer.alloc(257, 1).toString('base64')}, {b:'Ag==??'},
    {salt:''}, {protocol:'unknown'}, {iteration:0}, {iteration:1_000_001}, {iteration:2.1}, {c:''}]) {
    const client = await AppleSrp.create('alice', privateValue);
    await expect(client.complete('password123', {...challenge, protocol:'s2k', ...patch} as any)).rejects.toThrow();
  }
});

test('SRP uses fresh cryptographic ephemeral values', async () => {
  const one = await AppleSrp.create('alice');
  const two = await AppleSrp.create('alice');
  expect(one.publicKey).not.toBe(two.publicKey);
  expect(JSON.stringify(one)).toBe('{}');
});
